'use client';
import Link from 'next/link';
import { useEffect, useState } from 'react';
import { brandKitRequest } from './client';
import type { BrandKit } from './types';
export function BrandKitPicker({ value, onChange, disabled }: { value?: string; onChange: (id: string | undefined) => void; disabled?: boolean }) {
 const [kits, setKits] = useState<BrandKit[]>([]), [error, setError] = useState(''), [loading, setLoading] = useState(true);
 useEffect(() => { const controller = new AbortController(); void brandKitRequest({ signal: controller.signal }).then((data) => { setKits(data.kits); setLoading(false); }).catch((error) => { if (!controller.signal.aborted) { setError(error.message); setLoading(false); } }); return () => controller.abort(); }, []);
 return <div className="space-y-2 rounded-lg border p-3"><label className="block text-sm font-medium" htmlFor="full-auto-brand-kit">Brand Kit <span className="font-normal text-muted-foreground">· optional</span></label><select id="full-auto-brand-kit" className="h-10 w-full rounded-md border bg-background px-3 text

